values.content:
Write a PRD for this feature.

Feature: {{ $json.featureName }}
Product: {{ $json.productName || 'not specified' }}
Author: {{ $json.authorName || 'not specified' }}
PRD audience: {{ $json.prdAudience }}
Detail level: {{ $json.detailLevel }}

Problem statement:
{{ $json.problemStatement }}

Target users:
{{ $json.targetUsers || 'infer from problem statement' }}

Job stories:
{{ $json.jobStories.join('\n') || 'not specified — derive from problem' }}

Proposed solution:
{{ $json.proposedSolution || 'not specified — define approach' }}

Success metrics:
{{ $json.successMetrics.join('\n') || 'not specified — propose metrics' }}

Constraints:
{{ $json.constraints || 'none specified' }}

Out of scope:
{{ $json.outOfScope.join('\n') || 'not specified' }}

Existing behavior (if changing something):
{{ $json.existingBehavior || 'new feature' }}

Return JSON:
{"prd":{"title":"PRD: [Feature Name]","tldr":"1-2 sentence summary of the feature and why it matters","problem":"1-2 paragraphs on the problem — specific, with evidence or user quotes where derivable","target_users":{"primary":"","secondary":""},"job_stories":["When [situation], I want to [motivation], so I can [outcome]."],"proposed_solution":"2-3 paragraphs describing the solution approach — not implementation, but what the user experiences and why this approach","requirements":{"must_have":[{"id":"REQ-001","requirement":"","rationale":""}],"should_have":[{"id":"REQ-010","requirement":"","rationale":""}],"nice_to_have":[{"id":"REQ-020","requirement":""}]},"acceptance_criteria":[{"scenario":"Given [context], when [action], then [outcome]","edge_case":false}],"out_of_scope":["what this feature explicitly does NOT cover"],"success_metrics":[{"metric":"","baseline":"","target":"","measurement_method":""}],"open_questions":[{"question":"","owner":"","needed_by":""}],"technical_considerations":"anything the PM knows that engineering needs to factor in","dependencies":["other teams, systems, or features this depends on"]},"review_checklist":["questions stakeholders should answer before approving this PRD"]}
